record.field:
# Acción automatizada: sincronizar índice de color con criticidad
# Modelo: helpdesk.ticket
# Disparador: Al crear y actualizar (campo observado: x_studio_priority)

PRIORITY_TO_COLOR = {
    '3': 1,    # Crítica     -> Rojo
    '2': 3,    # Alta        -> Naranja
    '1': 10,   # Baja        -> Verde
    '0': 4,    # No asignada -> Azul claro
}

for record in records:
    new_color = PRIORITY_TO_COLOR.get(record.x_studio_priority, 0)
    if record.color != new_color:
        record.write({'color': new_color})

# Acción única para alertas críticas de helpdesk.

# Mapping: valor de x_studio_city -> (user_id manager, template_id)
CITY_CONFIG = {
    '1': (151, 112),  # Barcelona
    '2': (95, 113),  # Madrid    — TODO: poner user_id
    '3': (152, 114),  # Paris     — TODO: poner user_id
    '5': (144, 115),  # Amsterdam — TODO: poner user_id
}

MANAGER_KEYWORD = 'manager'


def _find_manager_email(user):
    """Devuelve el email del child contact con 'manager' en el nombre, o False."""
    if not user.partner_id:
        return False
    contact = user.partner_id.child_ids.filtered(
        lambda c: c.email and c.name and MANAGER_KEYWORD in c.name.lower()
    )[:1]
    return contact.email if contact else False


for record in records:
    city_value = record.x_studio_city

    # 1. Ciudad sin configurar
    config = CITY_CONFIG.get(city_value)
    if not config:
        record.message_post(
            body="Error: ciudad '%s' sin configuración en CITY_CONFIG." % city_value,
            subtype_xmlid='mail.mt_note',
        )
        continue

    user_id, template_id = config

    # 2. Usuario manager
    user = env['res.users'].browse(user_id).exists()
    if not user:
        record.message_post(
            body="Error: user_id %s configurado para ciudad '%s' no existe." % (user_id, city_value),
            subtype_xmlid='mail.mt_note',
        )
        continue

    # 3. Email del contacto "manager" bajo el partner del user
    manager_email = _find_manager_email(user)
    if not manager_email:
        record.message_post(
            body="Aviso: no se encontró contacto 'manager' bajo %s. Correo no se enviará." % user.display_name,
            subtype_xmlid='mail.mt_note',
        )

    # 4. Plantilla
    template = env['mail.template'].browse(template_id).exists()
    if not template:
        record.message_post(
            body="Error: plantilla con ID %s no encontrada (ciudad '%s')." % (template_id, city_value),
            subtype_xmlid='mail.mt_note',
        )
        continue

    # 5. Escribir asignación — change guard
    new_values = {}
    if record.user_id.id != user.id:
        new_values['user_id'] = user.id
    if record.partner_email != (manager_email or False):
        new_values['partner_email'] = manager_email or False
    if new_values:
        record.write(new_values)

    # 6. Enviar correo — solo si hay destinatario válido
    if not manager_email:
        continue

    try:
        template.send_mail(record.id, force_send=False)
    except Exception as e:
        record.message_post(
            body="Error al enviar plantilla ID %s: %s" % (template_id, e),
            subtype_xmlid='mail.mt_note',
        )

for ticket in records:
    if ticket.x_studio_invoice:
        ticket.x_studio_invoice.write({
            'x_studio_tickets': [(4, ticket.id)]
        })
